  { id: "INV-2026-1012", customer: "周予安", email: "yuan@yunfan.tech", avatar: "/images/blocks/people/zhou-yuan.jpg", amount: 58000, issuedAt: "2026-10-12", dueAt: "2026-11-12", status: "pending" },
