  company: string;
  phone: string;
  projects: number;
  since: string;
}

export const defaultClients: ClientRecord[] = [
  { id: "cl1", name: "陈思远", email: "siyuan@yuanshan.design", avatar: "/images/blocks/people/chen-siyuan.jpg", company: "远山设计", phone: "138 1024 5521", projects: 4, since: "2024-03-12" },
